const fs = require('fs');
const crypto = require('crypto');

const input = $('Input dari agent').first().json || {};
const siteRow = $input.first()?.json || {};

if (!siteRow.slug && !siteRow.domain) {
  return [{ json: { result: `ERROR: Website '${input.site || ''}' tidak ditemukan di database seo_sites. Panggil tool list_managed_sites untuk melihat daftar website yang tersedia.` } }];
}

const siteName = siteRow.name || 'Website';
const domain = siteRow.domain || '';
const gscProp = siteRow.gsc_property || `sc-domain:${domain}`;
const report = String(input.report || 'top_queries').toLowerCase();
const days = Math.min(Math.max(Number(input.days) || 28, 7), 480);
const limit = Math.min(Math.max(Number(input.limit) || 20, 1), 50);
const pageUrl = String(input.page_url || '').trim();
const queryFilter = String(input.query_contains || '').trim();

const credPath = '/credentials/gsc-service-account.json';
let sa = null;
try {
  if (fs.existsSync(credPath)) {
    sa = JSON.parse(fs.readFileSync(credPath, 'utf8'));
  } else if (process.env.GSC_SERVICE_ACCOUNT_JSON) {
    sa = JSON.parse(process.env.GSC_SERVICE_ACCOUNT_JSON);
  }
} catch (e) {
  return [{ json: { result: `ERROR: Gagal membaca file Service Account: ${e.message}` } }];
}

if (!sa || !sa.client_email || !sa.private_key) {
  return [{ json: { result: [
    '[GSC_NOT_CONFIGURED]',
    `Website: ${siteName} (${domain})`,
    `Target GSC Property: ${gscProp}`,
    'Status: File Service Account belum ditemukan di credentials/gsc-service-account.json.',
    '',
    'Panduan Menghubungkan Google Search Console:',
    '1. Buka Google Cloud Console -> Aktifkan Google Search Console API.',
    '2. Buat Service Account (IAM & Admin -> Service Accounts), lalu buat Key (format JSON).',
    '3. Simpan file tersebut ke folder: credentials/gsc-service-account.json',
    `4. Di Google Search Console property (${gscProp}): Settings -> Users & permissions -> Tambahkan email Service Account dengan izin "Restricted".`,
    '5. Setelah itu, panggil kembali perintah ini.',
    '[/GSC_NOT_CONFIGURED]'
  ].join('\n') } }];
}

const DATA_LAG_DAYS = 3;
const endD = new Date(Date.now() - DATA_LAG_DAYS * 86400000);
const startD = new Date(endD.getTime() - (days - 1) * 86400000);
const endStr = endD.toISOString().slice(0, 10);
const startStr = startD.toISOString().slice(0, 10);

const nowSec = Math.floor(Date.now() / 1000);
const header = { alg: 'RS256', typ: 'JWT' };
const claim = {
  iss: sa.client_email,
  scope: 'https://www.googleapis.com/auth/webmasters.readonly',
  aud: 'https://oauth2.googleapis.com/token',
  exp: nowSec + 3600,
  iat: nowSec
};
const b64 = o => Buffer.from(JSON.stringify(o)).toString('base64url');
const unsignedToken = `${b64(header)}.${b64(claim)}`;
const signer = crypto.createSign('RSA-SHA256');
signer.update(unsignedToken);
const sig = signer.sign(sa.private_key, 'base64url');
const jwtAssertion = `${unsignedToken}.${sig}`;

const tokenResp = await fetch('https://oauth2.googleapis.com/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion: jwtAssertion
  })
});

if (!tokenResp.ok) {
  const errBody = await tokenResp.text();
  return [{ json: { result: `ERROR: Gagal otorisasi Google OAuth (HTTP ${tokenResp.status}): ${errBody}` } }];
}
const tokenData = await tokenResp.json();
const accessToken = tokenData.access_token;

let dimensions = ['query'];
if (report === 'top_pages') dimensions = ['page'];
else if (report === 'striking_distance') dimensions = ['query', 'page'];
else if (report === 'low_ctr') dimensions = ['page'];

const filters = [];
if (pageUrl) filters.push({ dimension: 'page', operator: 'equals', expression: pageUrl });
if (queryFilter) filters.push({ dimension: 'query', operator: 'contains', expression: queryFilter });

const requestBody = {
  startDate: startStr,
  endDate: endStr,
  dimensions,
  rowLimit: report === 'striking_distance' ? 2000 : (report === 'low_ctr' ? 1000 : limit),
  type: 'web'
};
if (filters.length > 0) requestBody.dimensionFilterGroups = [{ filters }];

const gscUrl = `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodeURIComponent(gscProp)}/searchAnalytics/query`;
const gscResp = await fetch(gscUrl, {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${accessToken}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(requestBody)
});

if (!gscResp.ok) {
  const errBody = await gscResp.text();
  if (gscResp.status === 403) {
    return [{ json: { result: `[GSC_ACCESS_DENIED]\nAkses ditolak untuk property: ${gscProp}.\nPastikan email Service Account (${sa.client_email}) sudah ditambahkan sebagai user di Google Search Console untuk property tersebut dengan izin Restricted.\n[/GSC_ACCESS_DENIED]` } }];
  }
  return [{ json: { result: `ERROR: Google Search Console API error (HTTP ${gscResp.status}): ${errBody}` } }];
}

const gscData = await gscResp.json();
const rows = gscData.rows || [];

const EXPECTED_CTR = { 1: 0.28, 2: 0.15, 3: 0.10, 4: 0.07, 5: 0.05, 6: 0.04, 7: 0.03, 8: 0.025, 9: 0.02, 10: 0.018 };
const fmtRow = (r) => `klik: ${Math.round(r.clicks)} | impresi: ${Math.round(r.impressions)} | CTR: ${(r.ctr * 100).toFixed(1)}% | pos: ${r.position.toFixed(1)}`;

let outputLines = [];
let headerText = `[GSC_${report.toUpperCase()}] Property: ${gscProp} | ${startStr} s/d ${endStr} (${days} hari)`;

if (report === 'striking_distance') {
  headerText += ' | Filter: Posisi 8.0 - 20.0, Impresi >= 20 (Peluang Quick-Win Halaman 1)';
  const candidates = rows
    .filter(r => r.position >= 8.0 && r.position <= 20.0 && r.impressions >= 20)
    .sort((a, b) => b.impressions - a.impressions)
    .slice(0, limit);
  outputLines = candidates.map((r, i) => `${i + 1}. "${r.keys[0]}" -> ${r.keys[1]} | ${fmtRow(r)}`);
} else if (report === 'low_ctr') {
  headerText += ' | Filter: Top 10 Google tapi CTR di bawah standar industri (Kandidat Rewrite Title/Meta)';
  const candidates = [];
  for (const r of rows) {
    const posFloor = Math.round(r.position);
    if (posFloor >= 1 && posFloor <= 10 && r.impressions >= 50) {
      const expected = EXPECTED_CTR[posFloor] || 0.02;
      if (r.ctr < expected * 0.60) {
        candidates.push({ r, expected });
      }
    }
  }
  candidates.sort((a, b) => b.r.impressions - a.r.impressions);
  outputLines = candidates.slice(0, limit).map((c, i) => `${i + 1}. ${c.r.keys[0]} | ${fmtRow(c.r)} | Benchmark CTR Posisi ${Math.round(c.r.position)} ~${(c.expected * 100).toFixed(1)}%`);
} else if (report === 'top_pages') {
  outputLines = rows.slice(0, limit).map((r, i) => `${i + 1}. ${r.keys[0]} | ${fmtRow(r)}`);
} else {
  outputLines = rows.slice(0, limit).map((r, i) => `${i + 1}. "${r.keys[0]}" | ${fmtRow(r)}`);
}

if (!outputLines.length) {
  return [{ json: { result: `${headerText}\nNO_DATA: Tidak ada data yang cocok untuk kriteria ini pada periode ${days} hari terakhir.` } }];
}

return [{ json: { result: `${headerText}\n${outputLines.join('\n')}\n[/GSC_${report.toUpperCase()}]` } }];
